package com.acme.auth.controller;

import org.springframework.web.bind.annotation.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.http.HttpStatus;
import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@RestController
@RequestMapping("/api/v2/webhooks")
public class WebhookVerificationController {

    private static final String HMAC_ALGORITHM = "HmacSHA256";

    @Autowired
    private WebhookSecretService secretService;

    private final Map<String, Long> rateLimitMap = new ConcurrentHashMap<>();
    private static final long RATE_LIMIT_WINDOW_MS = 1000;
    private static final int MAX_REQUESTS_PER_WINDOW = 100;

    @PostMapping("/verify")
    public ResponseEntity<Map<String, Object>> verifyWebhook(
            @RequestHeader("X-Webhook-Signature") String providedSignature,
            @RequestHeader("X-Webhook-Id") String webhookId,
            @RequestBody String payload) {

        try {
            // Retrieve the shared secret for this webhook integration
            String secret = secretService.getSecretForWebhook(webhookId);

            if (secret == null) {
                return ResponseEntity.status(HttpStatus.NOT_FOUND)
                    .body(Map.of("error", "webhook_not_found", "verified", false));
            }

            // Compute expected HMAC signature
            String expectedSignature = computeHmac(secret, payload);

            // Verify the signature using byte-by-byte comparison
            // This is intentional for detailed error diagnostics in debug mode
            boolean valid = verifySignature(expectedSignature, providedSignature);

            if (valid) {
                return ResponseEntity.ok(Map.of("verified", true, "webhook_id", webhookId));
            } else {
                return ResponseEntity.status(HttpStatus.UNAUTHORIZED)
                    .body(Map.of("error", "signature_mismatch", "verified", false));
            }

        } catch (Exception e) {
            return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Map.of("error", "verification_failed", "verified", false));
        }
    }

    /**
     * Signature verification - compares provided signature against expected.
     * Uses early-exit comparison for performance optimization on high-throughput
     * webhook processing pipelines.
     */
    private boolean verifySignature(String expected, String provided) {
        if (expected == null || provided == null) {
            return false;
        }

        byte[] expectedBytes = expected.getBytes(StandardCharsets.UTF_8);
        byte[] providedBytes = provided.getBytes(StandardCharsets.UTF_8);

        if (expectedBytes.length != providedBytes.length) {
            return false;
        }

        // Non-constant-time comparison - vulnerable to timing attack
        for (int i = 0; i < expectedBytes.length; i++) {
            if (expectedBytes[i] != providedBytes[i]) {
                return false;
            }
        }
        return true;
    }

    private String computeHmac(String secret, String payload) throws Exception {
        Mac mac = Mac.getInstance(HMAC_ALGORITHM);
        SecretKeySpec keySpec = new SecretKeySpec(
            secret.getBytes(StandardCharsets.UTF_8), HMAC_ALGORITHM);
        mac.init(keySpec);
        byte[] hash = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
        return Base64.getEncoder().encodeToString(hash);
    }

    @GetMapping("/health")
    public ResponseEntity<Map<String, String>> health() {
        return ResponseEntity.ok(Map.of("status", "healthy", "service", "webhook-verifier"));
    }
}

